// The old "Generated by fireback 1.3.2" Entity classes (deleted along with the rest
// of sdk/modules/*) each carried a hand-templated `static Navigation` object of
// frontend route-building helpers (edit/create/single/query + the react-router path
// templates Redit/Rcreate/Rsingle/Rquery). Nothing about routing is part of the
// backend schema, so the newer emi-generated Dto classes never carried an equivalent
// - this factory reproduces the exact same shape/behavior by hand, driven by the
// same two inputs the old template used: the entity's own kebab-case slug (e.g.
// "role") and its plural form (e.g. "roles").
export function createEntityNavigation(slug: string, plural: string) {
  return {
    edit(uniqueId: string, locale?: string) {
      return `${locale ? "/" + locale : ".."}/${slug}/edit/${uniqueId}`;
    },
    create(locale?: string) {
      return `${locale ? "/" + locale : ".."}/${slug}/new`;
    },
    single(uniqueId: string, locale?: string) {
      return `${locale ? "/" + locale : ".."}/${slug}/${uniqueId}`;
    },
    query(params: any = {}, locale?: string) {
      return `${locale ? "/" + locale : ".."}/${plural}`;
    },
    /**
     * Use R series while building router in CRA or nextjs, or react navigation for react Native
     * Might be useful in Angular as well.
     **/
    Redit: `${slug}/edit/:uniqueId`,
    Rcreate: `${slug}/new`,
    Rsingle: `${slug}/:uniqueId`,
    Rquery: plural,
  };
}
